def seed_programs():
    from .models import Program
    for p in PROGRAMS: Program.objects.update_or_create(slug=p['slug'],defaults={k:v for k,v in p.items() if k!='slug'})

def territory_kind(code,name):
    if code=='643': return 'country'
    low=name.lower()
    if 'федеральный округ' in low: return 'district'
    if any(x in low for x in ['без ', 'кроме ', 'арктическ']) or not code.isdigit(): return 'aggregate'
    if 'автономный округ' in low or (len(code)==11 and code[2:]=='000000000'): return 'subject'
    if len(code)==11: return 'municipality'
    return 'unknown'
